export const SCROLLBACK_LINES = 10_000;
export const JOURNAL_FILE_BYTES = 32 * 1024 * 1024;
export const JOURNAL_FILES = 4;

export interface PaneScrollback {
  paneId: string;
  lines: number;
  journalPath: string;
}

export function scrollbackFor(paneId: string, workspaceDir: string): PaneScrollback {
  return {
    paneId,
    lines: SCROLLBACK_LINES,
    journalPath: `${workspaceDir}/scrollback/${paneId}.log`,
  };
}

