export interface TurnCost {
  runId: string;
  turnIx: number;
  model: string;
  usd: number;
}

export interface LedgerRow {
  run_id: string;
  turn_ix: number;
  model: string;
  usd_micros: number;
}

export function toMicros(usd: number): number {
  return Math.floor(usd * 1_000_000);
}

export function ledgerRow(cost: TurnCost): LedgerRow {
  return {
    run_id: cost.runId,
    turn_ix: cost.turnIx,
    model: cost.model,
    usd_micros: toMicros(cost.usd),
  };
}
